(1411370, 180844, 37719, '<td valign="top">I like the photo but the title turned me off completely.</td>', 'I like the photo but the title turned me off completely.', '2005-05-25 11:56:44.000000', NULL, 1),
(1411373, 181623, 35602, '<td valign="top">Nice shot.  I espectially liked the detail of the shell, and the way it mimicked the shape of the lines in the grains(was it glitter?)</td>', 'Nice shot.  I espectially liked the detail of the shell, and the way it mimicked the shape of the lines in the grains(was it glitter?)', '2005-05-25 11:57:26.000000', NULL, 1),
