(1424404, 181367, 38248, '<td valign="top">I have to give this one high points, not just because the colors and shapes are really nice, but wow! the patience and effort that must have gone into it.  Very nice.</td>', 'I have to give this one high points, not just because the colors and shapes are really nice, but wow! the patience and effort that must have gone into it.  Very nice.', '2005-05-31 22:46:16.000000', NULL, 1),
(1424412, 181129, 38248, '<td valign="top">Very nice, very abstract.  I like the hues and shapes on the black background.</td>', 'Very nice, very abstract.  I like the hues and shapes on the black background.', '2005-05-31 22:48:40.000000', NULL, 1),
(1424427, 181175, 33672, '<td valign="top">Great capture.. very crisp, nice colors!</td>', 'Great capture.. very crisp, nice colors!', '2005-05-31 22:53:02.000000', NULL, 1),
